import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('execute returns a ToolResponse naming the missing required property when a required field is omitted', async () => {
    const registry = new ToolRegistry();
    let callCount = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        callCount += 1;
        return 'sunny';
      }
    );

    const result = await registry.execute('get_weather', {});

    expect({
      callCount,
      mentionsLocation: result.result.includes('location'),
      mentionsRequired: /required/i.test(result.result),
    }).toEqual({
      callCount: 0,
      mentionsLocation: true,
      mentionsRequired: true,
    });
  });
});
